import { Session } from './src/session.js'
const turns=()=>Promise.resolve().then(()=>Promise.resolve())
let calls=0
const host={queryFn(ctx){calls++; return Promise.resolve(ctx.signal.aborted)},timers:{schedule(fn){fn()}}}
const s=new Session(host,{online:false})
const h=s.subscribe('fresh')
if(s.snapshot('fresh').fetchStatus!=='paused')throw Error('fresh query did not pause offline')
s.unsubscribe(h)
if(s.snapshot('fresh').fetchStatus!=='idle')throw Error('retired attempt did not restore idle')
s.online(true)
await turns()
if(calls!==0)throw Error('retired offline attempt entered after reconnect')
let cachedCalls=0
const c=new Session({queryFn(ctx){cachedCalls++; return Promise.resolve(ctx.signal.aborted)},timers:{schedule(fn){fn()}}},{online:false})
const ch=c.subscribe('cached',{initialData:'stop'})
c.unsubscribe(ch)
c.online(true)
await turns()
if(cachedCalls!==1)throw Error('cached background refresh did not resume')
let resolve, entered=0
const p=new Session({queryFn(){entered++;return new Promise(r=>resolve=r)},timers:{schedule(fn){fn()}}})
const ph=p.subscribe('entered')
p.unsubscribe(ph)
resolve('late')
await turns()
if(entered!==1||p.snapshot('entered').data!=='late')throw Error('unconsumed entered work no longer completed')
console.log('manual assertions passed')
EOF

